style.css:
/* Blue Voltage — Google */

/* colors you can swap */
:root {
  --my-bg: #050d20;
  --my-blue: #087bff;
  --my-electric: #00aaff;
  --my-light: #70caff;
  --my-text: #eaf5ff;
}

/* electric blue background */
html,
body {
  background:
    radial-gradient(ellipse at 20% 20%, #063d85 0%, transparent 45%),
    radial-gradient(ellipse at 80% 75%, #004b9e 0%, transparent 45%),
    linear-gradient(135deg, #020817, #071b3d, #001b45) !important;
  background-attachment: fixed !important;
  color: var(--my-text) !important;
}

/* blue text and links */
a {
  color: var(--my-light) !important;
  transition: color 0.2s ease !important;
}

a:hover {
  color: #ffffff !important;
  text-shadow: 0 0 10px var(--my-electric) !important;
}

/* rounded blue buttons */
button,
input[type="button"],
input[type="submit"],
[role="button"] {
  border-radius: 14px !important;
  border: 1px solid #168bff !important;
  background: linear-gradient(135deg, #086cff, #00aaff) !important;
  color: white !important;
  box-shadow: 0 0 12px #087bff55 !important;
  transition: 0.2s ease !important;
}

button:hover,
[role="button"]:hover {
  box-shadow: 0 0 22px #009dffbb !important;
  transform: translateY(-1px) !important;
}

/* rounded search boxes */
input,
textarea {
  border-radius: 16px !important;
  border: 1px solid #168bff !important;
  background: #071a36 !important;
  color: white !important;
  box-shadow: inset 0 0 8px #087bff22 !important;
}

/* blue selection highlight */
::selection {
  background: #087bff !important;
  color: white !important;
}

/* rounded images */
img {
  border-radius: 12px !important;
}

/* blue scrollbar */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-track {
  background: #061329 !important;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(#087bff, #00c3ff) !important;
  border-radius: 20px !important;
}

/* blue glow on focused elements */
:focus-visible {
  outline: 2px solid #00aaff !important;
  outline-offset: 3px !important;
}
